tokenRouteContent:
import { NextRequest, NextResponse } from 'next/server';

// [Velt] Get API key and auth token from environment variables
// Set these in .env.local - get them from https://console.velt.dev
const NEXT_PUBLIC_VELT_API_KEY = process.env.NEXT_PUBLIC_VELT_API_KEY || "6xTcUFtlYAlCdh11zrKB";
const VELT_AUTH_TOKEN = process.env.VELT_AUTH_TOKEN || "bd4d5226050470b6c658054fcdf1092a";

export async function POST(req: NextRequest) {
  try {
    const { userId, organizationId, email, isAdmin } = await req.json();
    if (!userId || !organizationId) {
      return NextResponse.json({ error: 'Missing userId or organizationId' }, { status: 400 });
    }
    if (!VELT_AUTH_TOKEN) {
      return NextResponse.json({ error: 'Server configuration error: missing VELT_AUTH_TOKEN' }, { status: 500 });
    }
    const body = {
      data: {
        userId,
        userProperties: {
          organizationId,
          ...(typeof isAdmin === 'boolean' ? { isAdmin } : {}),
          ...(email ? { email } : {}),
        },
      },
    };
    const res = await fetch('https://api.velt.dev/v2/auth/token/get', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'x-velt-api-key': NEXT_PUBLIC_VELT_API_KEY, 'x-velt-auth-token': VELT_AUTH_TOKEN },
      body: JSON.stringify(body),
    });
    const json = await res.json();
    const token = json?.result?.data?.token;
    if (!res.ok || !token) {
      return NextResponse.json({ error: json?.error?.message || 'Failed to generate token' }, { status: 500 });
    }
    return NextResponse.json({ token });
  } catch {
    return NextResponse.json({ error: 'Internal error' }, { status: 500 });
  }
}

veltInitializeUserContent:
"use client";

import { useAppUser } from "@/app/userAuth/useAppUser";
import type { VeltAuthProvider } from "@veltdev/types";
import { useMemo } from "react";

// [Velt] Call your backend API to generate a JWT token for the user
async function getVeltJwtFromBackend(user: {
  userId: string;
  organizationId: string;
  email?: string;
}) {
  const resp = await fetch("/api/velt/token", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      userId: user.userId,
      organizationId: user.organizationId,
      email: user.email,
      isAdmin: false,
    }),
    cache: "no-store",
  });
  if (!resp.ok) {
    const err = await resp.json().catch(() => ({}));
    throw new Error(`Token API failed: ${err?.error || resp.statusText}`);
  }
  const { token } = await resp.json();
  if (!token) throw new Error("No token in response");
  return token as string;
}

export function useVeltAuthProvider() {
  // [Velt] Get your app's current authenticated user to authenticate with Velt.
  const { user } = useAppUser();

  // NOTE: User saving is handled by the host app (AppUserContext.tsx) when
  // users log in. This keeps user management separate from the Velt implementation.
  // Users are fetched on-demand via the userDataProvider.get() method.

  // [Velt] Create auth provider object to pass to VeltProvider
  const authProvider: VeltAuthProvider | undefined = useMemo(() => {
    if (!user) return undefined;
    return {
      user,
      retryConfig: { retryCount: 3, retryDelay: 1000 },
      generateToken: async () => {
        return await getVeltJwtFromBackend({
          userId: user.userId as string,
          organizationId: user.organizationId as string,
          email: user.email,
        });
      },
    };
  }, [user]);

  return { authProvider };
}

veltInitializeDocumentContent:
'use client';
import { useEffect } from 'react';
import { useSetDocuments } from '@veltdev/react';
import { useCurrentDocument } from '@/app/document/useCurrentDocument';

export default function VeltInitializeDocument() {
  const { documentId, documentName } = useCurrentDocument();
  // [Velt] Get document setter hook
  const { setDocuments } = useSetDocuments();

  // [Velt] Set document in Velt. This is the resource where all Velt collaboration data will be scoped.
  useEffect(() => {
    if (!documentId || !documentName || !setDocuments) return;
    setDocuments([
      { id: documentId, metadata: { documentName: documentName } },
    ]);
  }, [setDocuments, documentId, documentName]);

  return null;
}

veltCollaborationContent:
"use client";
import { useVeltClient, VeltComments } from "@veltdev/react";
import VeltInitializeDocument from "./VeltInitializeDocument";
import { VeltCustomization } from "./ui-customization/VeltCustomization";
import { useEffect } from "react";
import { useAppUser } from "@/app/userAuth/useAppUser";

export function VeltCollaboration() {
  const { isUserLoggedIn } = useAppUser();
  // [Velt] Get Velt client instance
  const { client } = useVeltClient();

  // [Velt] Sign out user when user logs out, getting user login state from host app
  useEffect(() => {
    if (isUserLoggedIn === false && client) {
      client.signOutUser();
    }
  }, [isUserLoggedIn, client]);

  return (
    <>
      <VeltInitializeDocument />
      {/* [Velt] Comments configuration - popoverMode for inline comment dialogs */}
      <VeltComments
        popoverTriangleComponent={false}
        popoverMode={true}
        shadowDom={false}
        textMode={false}
        commentPinHighlighter={false}
        dialogOnHover={false}
        groupMatchedComments={true}
      />
      <VeltCustomization />
    </>
  );
}

veltDataProvidersContent:
// [Velt] Config-based data providers for self-hosting with Django backend
// Docs: https://docs.velt.dev/self-host-data/overview
//
// This uses the new config-based resolver endpoints where the SDK automatically
// handles HTTP requests, retries, and response formatting.

/* eslint-disable @typescript-eslint/no-explicit-any */

// Base URL for the Django backend API
// In development: http://localhost:8000/api/velt
// In production: your deployed Django API URL
const BACKEND_BASE_URL = process.env.NEXT_PUBLIC_SELF_HOSTING_BASE_URL || 'http://localhost:8000/api/velt';

// ============================================================
// Comment Data Provider (Config-Based)
// ============================================================
// The SDK will automatically make POST requests to these endpoints
// Request/Response formats are handled by the SDK

export const commentDataProvider = {
  config: {
    resolveTimeout: 20000,
    saveRetryConfig: {
      retryCount: 3,
      retryDelay: 2000
    },
    deleteRetryConfig: {
      retryCount: 3,
      retryDelay: 2000
    },
    getRetryConfig: {
      retryCount: 3,
      retryDelay: 2000
    },
    getConfig: {
      url: `${BACKEND_BASE_URL}/comments/get`,
      headers: {
        'Content-Type': 'application/json'
      }
    },
    saveConfig: {
      url: `${BACKEND_BASE_URL}/comments/save`,
      headers: {
        'Content-Type': 'application/json'
      }
    },
    deleteConfig: {
      url: `${BACKEND_BASE_URL}/comments/delete`,
      headers: {
        'Content-Type': 'application/json'
      }
    }
  }
} as any;

// ============================================================
// User Data Provider (Config-Based)
// ============================================================
// User resolver only supports getConfig (no save/delete)
// Request format: { organizationId: string, userIds: string[] }
// Response format: { data: Record<string, User>, success: boolean, statusCode: number }

export const userDataProvider = {
  config: {
    resolveTimeout: 5000,
    getRetryConfig: {
      retryCount: 3,
      retryDelay: 2000
    },
    getConfig: {
      url: `${BACKEND_BASE_URL}/users/get`,
      headers: {
        'Content-Type': 'application/json'
      }
    }
  }
} as any;

// ============================================================
// Attachment Data Provider (Config-Based)
// ============================================================
// When using saveConfig, the SDK automatically handles multipart/form-data uploads.
// No need for custom save() method - the SDK does it all!
//
// Save Request format (handled by SDK as multipart/form-data):
//   - file: File object (binary)
//   - request: JSON string with { attachment: {...}, metadata: {...} }
//
// Save Response format: { data: { url: string }, success: true, statusCode: 200 }

export const attachmentDataProvider = {
  config: {
    resolveTimeout: 30000, // Longer timeout for file uploads
    saveRetryConfig: {
      retryCount: 3,
      retryDelay: 2000
    },
    deleteRetryConfig: {
      retryCount: 3,
      retryDelay: 2000
    },
    saveConfig: {
      url: `${BACKEND_BASE_URL}/attachments/save`,
      // Note: Don't set Content-Type - browser will set multipart/form-data with boundary
    },
    deleteConfig: {
      url: `${BACKEND_BASE_URL}/attachments/delete`,
      headers: {
        'Content-Type': 'application/json'
      }
    }
  }
} as any;

// ============================================================
// Reaction Data Provider (Config-Based)
// ============================================================
// The SDK will automatically make POST requests to these endpoints

export const reactionDataProvider = {
  config: {
    resolveTimeout: 5000,
    saveRetryConfig: {
      retryCount: 3,
      retryDelay: 2000
    },
    deleteRetryConfig: {
      retryCount: 3,
      retryDelay: 2000
    },
    getRetryConfig: {
      retryCount: 3,
      retryDelay: 2000
    },
    getConfig: {
      url: `${BACKEND_BASE_URL}/reactions/get`,
      headers: {
        'Content-Type': 'application/json'
      }
    },
    saveConfig: {
      url: `${BACKEND_BASE_URL}/reactions/save`,
      headers: {
        'Content-Type': 'application/json'
      }
    },
    deleteConfig: {
      url: `${BACKEND_BASE_URL}/reactions/delete`,
      headers: {
        'Content-Type': 'application/json'
      }
    }
  }
} as any;

